  // conn(X,Y) :- edge(X,Y).
  (function() {
    return _.flatten(map(function(e1) {
      var X = e1.t[0];
      var Y = e1.t[1];
      return [['conn', [X, Y], e1.v]];
    }, _.values(edge)));
  })(),
