      return _.flatten(map(function(e1) {
        var X = e1.t[0];
        var Y = e1.t[1];
        return [['path', [X, Y], e1.v]];
      }, _.values(conn)));
    })(),
    // path(X,Y) :- conn(X,Z), path(Z,Y).
