};
var rels_path = stages_path([{}], 0, -1);
var path = rels_path[0];

// component 0 bool
// component 1 bool
// component 2 bool
// component 3 bool
var model = function() {
  return [holds(path, ['phenotype_mim_104300', 'gene_entrezgene_351'])(),
          holds(path, ['phenotype_mim_104300', 'gene_entrezgene_323'])(),
          holds(path, ['phenotype_mim_104300', 'gene_entrezgene_590'])(),
          holds(path, ['phenotype_mim_104300', 'gene_entrezgene_5126'])()];
};
Infer({method: 'enumerate'}, model);

